Add-Type -AssemblyName System.Security
$u = Read-Host 'Admin username'
$p = Read-Host 'Admin password' -AsSecureString
$b = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($p)
try { $plain=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($b); $salt=New-Object byte[] 16; [Security.Cryptography.RandomNumberGenerator]::Fill($salt); $hash=[Security.Cryptography.Rfc2898DeriveBytes]::Pbkdf2($plain,$salt,210000,[Security.Cryptography.HashAlgorithmName]::SHA256,32); $cs=if($env:ASHKAN_BANK_DB){$env:ASHKAN_BANK_DB}else{'Server=localhost;Database=AshkanBankSphere;Integrated Security=True;TrustServerCertificate=True;'}; Add-Type -AssemblyName System.Data; $c=New-Object System.Data.SqlClient.SqlConnection($cs);$c.Open();try{$cmd=$c.CreateCommand();$cmd.CommandText='INSERT INTO Users(Username,PasswordHash,PasswordSalt) VALUES(@u,@h,@s)';$null=$cmd.Parameters.Add('@u',[Data.SqlDbType]::NVarChar,100);$cmd.Parameters['@u'].Value=$u;$null=$cmd.Parameters.Add('@h',[Data.SqlDbType]::VarBinary,32);$cmd.Parameters['@h'].Value=$hash;$null=$cmd.Parameters.Add('@s',[Data.SqlDbType]::VarBinary,16);$cmd.Parameters['@s'].Value=$salt;$cmd.ExecuteNonQuery()|Out-Null;Write-Host 'Admin created'}finally{$c.Dispose()}}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($b)}
